function validate([nums1, nums2]) {
  if (!Array.isArray(nums1) || !Array.isArray(nums2)) return 'nums1 and nums2 must be arrays.';
  const n = nums1.length;
  if (nums2.length !== n) return 'nums1 and nums2 must have the same length.';
  if (n < 3 || n > 100000) return 'n is between 3 and 10^5.';
  for (const list of [nums1, nums2]) {
    const seen = new Array(n).fill(false);
    for (const v of list) {
      if (!Number.isInteger(v) || v < 0 || v >= n || seen[v]) return 'Each array must be a permutation of 0..n-1.';
      seen[v] = true;
    }
  }
  return null;
}

