function goodTriplets(nums1, nums2) {
  const n = nums1.length;
  const where = new Array(n);
  for (let i = 0; i < n; i++) {
    where[nums2[i]] = i;
  }

  const tree = new Array(n + 1).fill(0);
  let count = 0;
  for (let i = 0; i < n; i++) {
    const pos = where[nums1[i]];
    let smallerBefore = 0;
    for (let k = pos; k > 0; k -= k & -k) {
      smallerBefore += tree[k];
    }
    const largerAfter = (n - 1 - pos) - (i - smallerBefore);
    count += smallerBefore * largerAfter;
    for (let k = pos + 1; k <= n; k += k & -k) {
      tree[k]++;
    }
  }
  return count;
}

