function goodTriplets(nums1, nums2) {
  const n = nums1.length;
  const p1 = new Array(n), p2 = new Array(n);
  nums1.forEach((v, i) => { p1[v] = i; });
  nums2.forEach((v, i) => { p2[v] = i; });
  let total = 0;
  for (let x = 0; x < n; x++)
    for (let y = 0; y < n; y++)
      for (let z = 0; z < n; z++)
        if (p1[x] < p1[y] && p1[y] < p1[z] && p2[x] < p2[y] && p2[y] < p2[z]) total++;
  return total;
}

