function generate(rand, size) {
  const n = size === 'large' ? 2000 - Math.floor(rand() * 10) : 3 + Math.floor(rand() * 7);
  const shuffle = (list) => {
    for (let i = list.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [list[i], list[j]] = [list[j], list[i]];
    }
    return list;
  };
  const nums1 = shuffle(Array.from({ length: n }, (_, i) => i));
  const mode = rand();
  let nums2;
  if (mode < 0.4) {
    nums2 = shuffle(Array.from({ length: n }, (_, i) => i));
  } else if (mode < 0.55) {
    nums2 = [...nums1].reverse();
  } else {
    // Mostly the same order with a few swaps, so many triplets survive.
    nums2 = [...nums1];
    const swaps = 1 + Math.floor(rand() * Math.max(1, n / 4));
    for (let s = 0; s < swaps; s++) {
      const i = Math.floor(rand() * n), j = Math.floor(rand() * n);
      [nums2[i], nums2[j]] = [nums2[j], nums2[i]];
    }
  }
  return [nums1, nums2];
}
